var n=`0676-foutou-banane`;var a=`world-0676`;var i=`CI`;var s=`western-africa`;var o=4;var r=60;var l={en:`Foutou Banane`,ua:`Футу з бананів`};var u={en:`Foutou Banane is a Côte d'Ivoire classic prepared with plantain, cassava root, yellow onion, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Футу з бананів, страва кухні країни Кот-д'Івуар зі складниками: плантан, маніок, жовта цибуля, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 27 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 27 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:27,i:[[`plantain`,650,`g`],[`cassava-root`,460,`g`],[`water`,1050,`ml`]]},{en:`Pound well-cooked plantain and cassava together into a cohesive, stretchy mass and form smooth portions.`,ua:`Розтовчіть добре зварені плантан і маніок до однорідної тягучої маси та сформуйте гладкі порції.`,t:[`mashing`,`pounding`],m:17,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,180,`g`],[`red-palm-oil`,45,`ml`],[`tomato`,250,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`peanut-sauce`,180,`g`],[`table-salt`,null,`to_taste`]]}];var g={slug:n,id:a,country:`CI`,region:s,servings:4,minutes:60,title:l,text:u,steps:d};export{i as country,g as default,a as id,r as minutes,s as region,o as servings,n as slug,d as steps,u as text,l as title};